import {RULES,RULE_VERSION,uid,dateKey,addDays,extract,validate,triage,guardian,plan,draftReferral} from './engine.js';
import {openStore,readState,writeState,seed} from './store.js';
const paths={home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-3.87M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8m8-7.87a4 4 0 0 1 0 7.75',calendar:'M8 2v4m8-4v4M3 10h18M5 4h14a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2m2 10h3m4 0h3m-10 4h3',mic:'M12 2a3 3 0 0 0-3 3v7a3 3 0 0 0 6 0V5a3 3 0 0 0-3-3m7 8v2a7 7 0 0 1-14 0v-2m7 9v3m-4 0h8',flag:'M4 22V3m0 0c5-4 11 4 16 0v12c-5 4-11-4-16 0',chart:'M3 3v18h18M7 15v3m5-8v8m5-12v12',settings:'m9 3-1 3-3 1-2 4 2 3 1 4 4 3 3-2 4-1 3-4-2-3-1-4-4-3-3 2zM12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8',help:'M9.1 9a3 3 0 0 1 5.8 1c0 2-3 3-3 3m.1 4h.01M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20',chevron:'m9 5 7 7-7 7',arrow:'M4 12h16m-6-6 6 6-6 6',check:'m5 12 4 4L19 6',shield:'m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6z m-5 10 3 3 5-6',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9m-8 12h4',globe:'M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20m0 0c-5 5-5 15 0 20 5-5 5-15 0-20M2 12h20',wifi:'M2 8a16 16 0 0 1 20 0M5 12a11 11 0 0 1 14 0m-10 4a5 5 0 0 1 6 0m-3 4h.01',clock:'M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20m0 4v6l4 2',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8',alert:'m12 3 10 18H2L12 3m0 6v5m0 3h.01',plus:'M12 5v14M5 12h14',search:'M21 21l-5-5M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14',file:'M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8l-6-6m0 0v6h6M8 13h8m-8 4h5',download:'M12 3v12m-5-5 5 5 5-5M3 15v6h18v-6',close:'m6 6 12 12M6 18 18 6',menu:'M3 6h18M3 12h18M3 18h18',volume:'m11 5-6 4H2v6h3l6 4V5m4 3a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14',leaf:'M20 3C6 1 1 10 5 17c7 7 17 0 15-14M4 21 16 9',refresh:'M20 7v5h-5M4 17v-5h5M5.1 7a8 8 0 0 1 13.2-3L20 7M4 17l1.7 3A8 8 0 0 0 19 17'};
const icon=(n)=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.file}"/></svg>`;
const esc=(s)=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const app=document.querySelector('#app'),modal=document.querySelector('#modal');
let state,page='overview',filter='all',search='',draft=null,recording=null,recordingAudio=null,audioChunks=[],audioURL=null,recorderTimer=null,pendingAudio=null,recordingActive=false,recordStart=0,saveBusy=false;
const labels={overview:'Overview',beneficiaries:'Beneficiaries',visits:'Visit records',followups:'Follow-ups',referrals:'Referrals',supervisor:'ANM dashboard',insights:'Impact & activity',settings:'Settings & safety',record:'Record a visit'};
const categoryLabels={pregnant:'Maternal care',child:'Child health',infant:'Infant care',tb:'TB care',ncd:'NCD care'};
const hindi={overview:'एक नज़र',beneficiaries:'लाभार्थी',visits:'मुलाकात रिकॉर्ड',followups:'फॉलो-अप',referrals:'रेफरल',supervisor:'ANM डैशबोर्ड',insights:'प्रगति',settings:'सेटिंग्स',record:'मुलाकात दर्ज करें'};
const title=p=>state.settings.language==='hi-IN'?(hindi[p]||labels[p]):labels[p];
const beneficiary=id=>state.beneficiaries.find(b=>b.id===id);
const initials=name=>name.split(' ').slice(0,2).map(w=>w[0]).join('');
const avatar=b=>`<div class="avatar ${b.color||''}" aria-hidden="true">${esc(initials(b.name))}</div>`;
const activeFlags=()=>state.flags.filter(f=>f.status==='open');
const pendingTasks=()=>state.tasks.filter(t=>t.status==='pending');
const badge=(text,color='neutral')=>`<span class="badge ${color}">${esc(text)}</span>`;
const nowDate=()=>new Date().toLocaleDateString(state.settings.language,{weekday:'short',day:'numeric',month:'short',year:'numeric'});
const dueLabel=d=>d===dateKey()?'Today':d<dateKey()?'Overdue':new Date(d+'T12:00:00').toLocaleDateString('en-IN',{day:'numeric',month:'short'});
const toast=text=>{const el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),4000);};
async function persist(){await writeState(state);}
function audit(agent,action,extra={}){state.audit.unshift({id:uid(),timestamp:new Date().toISOString(),agent,action,rule_version:RULE_VERSION,...extra});}
function navigate(target){stopRecording();if(audioURL){URL.revokeObjectURL(audioURL);audioURL=null;}page=target;filter='all';search='';render();window.scrollTo(0,0);}
function shell(content){return `<div class="shell"><aside class="sidebar"><div class="brand"><img src="icon.svg" alt=""><div><strong>ASHA Sahayak</strong><small>YOUR CARE COMPANION</small></div></div><div class="workspace-label">WORKSPACE</div><nav class="nav" aria-label="Main navigation">${[['overview','home'],['beneficiaries','users'],['visits','file'],['followups','calendar'],['referrals','flag'],['supervisor','shield'],['insights','chart']].map(([id,ic])=>`<button data-nav="${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}>${icon(ic)}${title(id)}${id==='followups'?`<span class="count">${pendingTasks().length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="offline-card"><h4>${icon('wifi')}Care continues, offline.</h4><p>Your records are saved on this device. Keep going, even without a signal.</p><button data-action="sync">${state.outbox.length?`${state.outbox.length} record(s) pending sync`:'View storage & sync'} ${icon('arrow')}</button></div><nav class="nav" style="margin-top:17px"><button data-nav="settings" class="${page==='settings'?'active':''}">${icon('settings')}${title('settings')}</button></nav><div class="profile"><div class="avatar peach">LK</div><div><strong>Lakshmi Kumari</strong><small>ASHA worker · Rampur PHC</small></div></div></div></aside><div class="main-wrap"><header class="topbar"><div class="breadcrumb"><button class="icon-btn mobile-menu" aria-label="Open navigation" data-action="menu">${icon('menu')}</button><span class="home-crumb">My workspace</span><span class="home-crumb">/</span><span>${title(page)}</span></div><div class="top-actions"><span class="connected"><i class="dot" style="${navigator.onLine?'':'background:#c39050'}"></i>${navigator.onLine?'Device online':'Working offline'}</span><label class="language">${icon('globe')}<span class="sr-only">Language</span><select id="language"><option value="en-IN" ${state.settings.language==='en-IN'?'selected':''}>English</option><option value="hi-IN" ${state.settings.language==='hi-IN'?'selected':''}>हिन्दी</option></select></label><button class="icon-btn" aria-label="View priority cases" data-nav="supervisor">${icon('bell')}</button><div class="avatar peach">LK</div></div></header><main>${content}<footer class="page-footer"><span>${icon('shield')}Decision support only. Follow clinical judgement and official protocols.</span><span>Synthetic demo · Made for the people who care.</span></footer></main></div></div>`;}
function heading(name,description,action=''){return `<div class="heading"><div><div class="eyebrow">RAMPUR PHC · WARD 01–03</div><h1>${name}</h1><p>${description}</p></div>${action||`<div class="date-chip">${icon('calendar')}${nowDate()}</div>`}</div>`;}
function stats(){const visits=state.visits.filter(v=>v.timestamp.slice(0,10)===new Date().toISOString().slice(0,10));const done=state.tasks.filter(t=>t.status==='completed');return `<div class="stats">${[['Visits recorded',visits.length,'file','Saved on this device','green'],['Beneficiaries',state.beneficiaries.length,'users',`${state.households.length} households in your care`,''],['Follow-ups due',pendingTasks().filter(t=>t.due_date<=dateKey()).length,'calendar',`${pendingTasks().filter(t=>t.due_date<dateKey()).length} overdue · let’s catch up`,'orange'],['Priority cases',activeFlags().length,'heart','Need your attention','orange']].map(([label,value,ic,foot,color])=>`<div class="stat"><div class="stat-top">${label}${icon(ic)}</div><div class="stat-value">${value.toString().padStart(2,'0')}</div><div class="stat-bottom"><span class="${color}">${foot}</span></div></div>`).join('')}</div>`;}
function taskRow(t){const b=beneficiary(t.beneficiary_id);if(!b)return '';return `<div class="visit-row">${avatar(b)}<div class="visit-info"><h3>${esc(b.name)}</h3><p>${esc(t.type)} <span>·</span> Ward ${esc(b.ward)}</p></div><div class="row-end">${badge(t.status==='completed'?'Completed':dueLabel(t.due_date),t.status==='completed'?'green':t.due_date<dateKey()?'red':'orange')}<button data-action="${t.status==='completed'?'person':'task'}" data-id="${t.status==='completed'?b.id:t.id}">${t.status==='completed'?'View':'Open'} ${icon('chevron')}</button></div></div>`;}
function alertCard(f){const b=beneficiary(f.beneficiary_id);return `<div class="alert-card"><div class="alert-top"><strong>${icon('alert')}${esc(b?.name||'Beneficiary')}</strong>${badge(f.severity==='urgent'?'Urgent':'Review',f.severity==='urgent'?'red':'orange')}</div><p>${esc(f.reason)}</p><button class="text-btn" data-action="flag" data-id="${f.id}">Review case ${icon('arrow')}</button></div>`;}
function overview(){const tasks=state.tasks.filter(t=>filter==='completed'?t.status==='completed':filter==='overdue'?t.status==='pending'&&t.due_date<dateKey():t.status==='pending'&&t.due_date<=dateKey());const greeting=state.settings.language==='hi-IN'?'नमस्ते, लक्ष्मी':'Namaste, Lakshmi';return `${heading(`${greeting} <span style="font-size:25px;color:#bb9767">☀</span>`,'A little care, a healthier community. Here’s your day at a glance.')}<section class="hero"><div class="hero-content"><div class="tag">${icon('leaf')}LESS PAPERWORK. MORE PEOPLE.</div><h2>Your voice. Their better care.</h2><p>Tell us about your visit. We’ll help with the records,<br>follow-ups, and the little things that matter.</p><div class="hero-actions"><button class="primary" data-action="new-visit">${icon('mic')}${title('record')}</button><span class="subtle">Speak in English or हिन्दी</span></div></div><div class="hero-art" aria-hidden="true"><div class="ring"></div><div class="paper">${icon('heart')}<i></i><i></i><i></i></div><div class="mic-circle">${icon('mic')}</div><span class="spark">✧</span></div></section>${stats()}<div class="dashboard-grid"><div><section class="panel"><div class="panel-header"><div><h2>Your visits & follow-ups</h2><p>Small steps that keep your community healthy.</p></div><button class="text-btn" data-nav="followups">View all ${icon('arrow')}</button></div><div class="tabs" role="tablist">${[['all','Today'],['overdue','Overdue'],['completed','Completed']].map(([k,l])=>`<button role="tab" aria-selected="${filter===k}" class="${filter===k?'selected':''}" data-filter="${k}">${l}<span class="tiny">${state.tasks.filter(t=>k==='completed'?t.status==='completed':t.status==='pending'&&(k==='overdue'?t.due_date<dateKey():t.due_date<=dateKey())).length}</span></button>`).join('')}</div>${tasks.length?tasks.slice(0,5).map(taskRow).join(''):'<div class="empty">All caught up. A little breathing room for your day.</div>'}</section><section class="panel"><div class="panel-header"><h2>Recent activity</h2><button class="text-btn" data-nav="insights">View activity ${icon('arrow')}</button></div><div class="activity">${state.audit.slice(0,3).map(a=>`<div class="activity-item"><div class="activity-icon">${icon('check')}</div><div><p>${esc(a.action)}</p><small>${esc(a.agent)}</small></div><time>${new Date(a.timestamp).toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'})}</time></div>`).join('')}</div></section></div><div><section class="panel"><div class="panel-header"><div><h2>Needs a little extra care</h2><p>Flagged early. Supported together.</p></div>${badge(`${activeFlags().length} open`,'orange')}</div>${activeFlags().slice(0,3).map(alertCard).join('')||'<div class="empty">No open flags. Continue routine care.</div>'}<div class="alert-footer">${icon('shield')} Every flag has a reason. You make the decision.</div></section><div class="care-tip">${icon('leaf')}<div><h3>A moment for you, too</h3><p>You look after everyone. Remember to take a water break between visits. Your wellbeing matters.</p></div></div></div></div>`;}
function beneficiaryPage(){const list=state.beneficiaries.filter(b=>(filter==='all'||b.category===filter)&&`${b.name} ${b.code} ${b.ward}`.toLowerCase().includes(search.toLowerCase()));return `${heading('Your community','Every person, every household, a continuous story of care.',`<button class="primary" data-action="add-person">${icon('plus')}Add beneficiary</button>`)}<div class="toolbar"><label class="search">${icon('search')}<input id="search" value="${esc(search)}" placeholder="Search by name, ID, or ward" aria-label="Search beneficiaries"></label><select id="category-filter" aria-label="Filter category"><option value="all">All care groups</option>${Object.entries(categoryLabels).map(([k,v])=>`<option value="${k}" ${filter===k?'selected':''}>${v}</option>`).join('')}</select></div><section class="panel"><div class="panel-header"><h2>Beneficiaries <span style="color:#93a085;font-weight:400">(${list.length})</span></h2><span class="badge neutral">Synthetic records</span></div>${list.map(b=>`<div class="visit-row">${avatar(b)}<div class="visit-info"><h3>${esc(b.name)}</h3><p>${esc(b.code)} <span>·</span> ${esc(b.detail||`${b.age} years`)} <span>·</span> Ward ${esc(b.ward)}</p></div><div class="row-end">${badge(categoryLabels[b.category],b.category==='pregnant'?'purple':'green')}<button data-action="person" data-id="${b.id}">View record ${icon('chevron')}</button></div></div>`).join('')||'<div class="empty">No beneficiaries match your search.</div>'}</section>`;}
function followups(){const list=state.tasks.filter(t=>(filter==='all'||t.status===filter)&&`${beneficiary(t.beneficiary_id)?.name} ${t.type}`.toLowerCase().includes(search.toLowerCase())).sort((a,b)=>a.due_date.localeCompare(b.due_date));return `${heading('Keep care moving','A clear next step, so nobody slips through the gaps.',`<button class="primary" data-action="add-task">${icon('plus')}Add follow-up</button>`)}<div class="toolbar"><label class="search">${icon('search')}<input id="search" value="${esc(search)}" placeholder="Search follow-ups" aria-label="Search follow-ups"></label><select id="category-filter" aria-label="Task status">${['all','pending','completed'].map(k=>`<option value="${k}" ${filter===k?'selected':''}>${k==='all'?'All follow-ups':k[0].toUpperCase()+k.slice(1)}</option>`).join('')}</select></div><section class="panel">${list.map(taskRow).join('')||'<div class="empty">No follow-ups here yet.</div>'}</section>`;}
function visitsPage(){return `${heading('A record of every visit','Confirmed observations, with the details you need.',`<button class="primary" data-action="new-visit">${icon('mic')}Record a visit</button>`)}<section class="panel">${[...state.visits].reverse().map(v=>{const b=beneficiary(v.beneficiary_id);return `<div class="visit-row">${avatar(b)}<div class="visit-info"><h3>${esc(b.name)}</h3><p>${new Date(v.timestamp).toLocaleDateString('en-IN',{day:'numeric',month:'short'})} <span>·</span> ${esc(categoryLabels[b.category])} <span>·</span> ${v.synthetic?'Demo visit':'Worker confirmed'}</p></div><div class="row-end">${badge(state.flags.some(f=>f.visit_id===v.id&&f.status==='open')?'Flagged':'Recorded',state.flags.some(f=>f.visit_id===v.id&&f.status==='open')?'orange':'green')}<button data-action="visit" data-id="${v.id}">View ${icon('chevron')}</button></div></div>`;}).join('')||'<div class="empty">Your confirmed visits will appear here.</div>'}</section>`;}
function recordPage(){if(draft?.stage==='review')return reviewPage();return `${heading('A visit, in your own words','Speak naturally. Review the details. Keep the care going.')}<div class="steps"><span class="current">01 · Capture</span><i></i><span>02 · Review</span><i></i><span>03 · Save & plan</span></div><section class="content-card" style="max-width:850px"><h2>Who did you visit?</h2><div class="form-field"><label for="visit-person">Beneficiary</label><select id="visit-person">${state.beneficiaries.map(b=>`<option value="${b.id}" ${draft?.beneficiary_id===b.id?'selected':''}>${esc(b.name)} · ${esc(b.code)} · ${categoryLabels[b.category]}</option>`).join('')}</select></div><div class="recorder"><button id="record-toggle" class="record-button" data-action="record-toggle" aria-label="Start voice recording">${icon('mic')}</button><div><h3 id="record-label">Tap to tell us about the visit</h3><p id="record-help">${state.settings.language==='hi-IN'?'हिन्दी में बोलें · रिकॉर्ड की समीक्षा करें':'Speak in English · You can edit the transcript below'}</p></div></div><div id="audio-preview"></div><div class="form-field"><label for="transcript">Visit notes / transcript</label><textarea id="transcript" rows="5" placeholder="For example: Visited Savitri, 7 months pregnant. BP 150 by 100. She reports a headache and swelling in her feet.">${esc(draft?.transcript||'')}</textarea><small>Browser speech recognition may require an internet connection. Offline audio can be retained on this device; type or correct the transcript to continue.</small></div><button class="text-btn" data-action="sample">Try a synthetic sample ${icon('arrow')}</button><div class="notice">Demo extraction handles a limited set of English and Hindi phrases. Verify every field. Use synthetic data only; this demo is not a clinical system.</div><label class="check"><input id="consent" type="checkbox" ${draft?.consent?'checked':''}>I have consent to record this visit and understand that browser speech recognition may send audio to its provider.</label><div class="actions"><button class="primary" data-action="extract">Review visit ${icon('arrow')}</button><button class="secondary" data-nav="overview">Cancel</button></div></section>`;}
function field(name,label,value,options=''){return `<div class="form-field"><label for="${name}">${label}</label><input id="${name}" name="${name}" type="number" value="${esc(value??'')}" ${options}><small>Leave blank if not measured or unknown.</small></div>`;}
function reviewPage(){const r=draft.record,b=beneficiary(r.beneficiary_id);return `${heading('Let’s get the details right','Your confirmation keeps the record accurate and the next steps useful.')}<div class="steps"><span>01 · Capture</span><i></i><span class="current">02 · Review</span><i></i><span>03 · Save & plan</span></div><section class="content-card" style="max-width:850px"><div class="visit-row" style="padding:0 0 20px">${avatar(b)}<div class="visit-info"><h3>${esc(b.name)}</h3><p>${esc(b.code)} · ${categoryLabels[b.category]}</p></div><button class="secondary" data-action="readback">${icon('volume')}Read back</button></div><div class="notice">${esc(draft.question)}</div><form id="confirm-form"><div class="form-grid">${field('bp_systolic','Systolic BP (mmHg)',r.bp_systolic,'min="50" max="300"')}${field('bp_diastolic','Diastolic BP (mmHg)',r.bp_diastolic,'min="30" max="200"')}${b.category==='pregnant'?field('gestation_months','Gestation (months)',r.gestation_months,'min="1" max="10"'):''}${['child','infant'].includes(b.category)?field('muac_cm','MUAC (cm)',r.muac_cm,'min="5" max="40" step="0.1"'):''}${field('cough_days','Cough duration (days)',r.cough_days,'min="0" max="365"')}<div class="form-field full"><label for="symptoms">Reported symptoms</label><input id="symptoms" name="symptoms" value="${esc(r.symptoms.join(', ').replaceAll('_',' '))}" placeholder="e.g. headache, swelling"><small>Separate symptoms with commas. Remove any symptoms that were denied.</small></div><div class="form-field full"><label for="advice">Advice already given</label><input name="advice" id="advice" placeholder="Document what you actually advised"></div></div><details><summary style="font-size:12px;cursor:pointer;margin:15px 0">Original visit note</summary><div class="quote">${esc(draft.transcript)}</div></details><label class="check"><input name="confirmed" type="checkbox" required>I checked the beneficiary, measurements, and symptoms. Blank fields were not measured or are unknown.</label><div class="actions"><button class="primary" type="submit">${icon('check')}Confirm & save visit</button><button class="secondary" type="button" data-action="edit-draft">Edit visit note</button></div></form></section>`;}
function supervisor(){const open=activeFlags();return `${heading('A shared view of care','Priority cases and overdue follow-ups for the ANM / PHC.')}<div class="notice">Demonstration supervisor view on this device. Production role-based access and shared clinical records are not enabled.</div>${stats()}<div class="dashboard-grid"><section class="panel"><div class="panel-header"><h2>Open risk flags</h2>${badge(`${open.length} cases`,'orange')}</div>${open.map(alertCard).join('')||'<div class="empty">No open flags.</div>'}</section><section class="panel"><div class="panel-header"><h2>Overdue follow-ups</h2></div>${pendingTasks().filter(t=>t.due_date<dateKey()).map(taskRow).join('')||'<div class="empty">No overdue follow-ups.</div>'}</section></div>`;}
function referralsPage(){return `${heading('Connect to the next level of care','Review, copy, and share a clear referral through your approved channel.')}<div class="notice">Referrals are drafts only. This app never sends a message automatically. Copying a draft does not mark it as sent.</div><section class="panel">${state.referrals.map(r=>`<div class="visit-row">${avatar(beneficiary(r.beneficiary_id))}<div class="visit-info"><h3>${esc(beneficiary(r.beneficiary_id).name)}</h3><p>For ANM / PHC <span>·</span> ${new Date(r.timestamp).toLocaleDateString('en-IN')}</p></div><div class="row-end">${badge('Draft','orange')}<button data-action="referral" data-id="${r.id}">Review ${icon('chevron')}</button></div></div>`).join('')||'<div class="empty">No referral drafts yet.<br>Review a priority case to prepare a referral.</div>'}</section>`;}
function insights(){const real=state.visits.filter(v=>!v.synthetic);const average=real.length?Math.round(real.reduce((a,v)=>a+v.duration_seconds,0)/real.length):null;return `${heading('Small actions. Visible progress.','A transparent activity log for your workspace.',`<button class="secondary" data-action="export">${icon('download')}Export records</button>`)}<div class="stats">${[['New records',real.length],['Mean recording time',average===null?'—':`${average}s`],['Tasks completed',state.tasks.filter(t=>t.status==='completed').length],['Agent decisions',state.audit.length]].map(([l,v])=>`<div class="stat"><div class="stat-top">${l}</div><div class="stat-value">${v}</div></div>`).join('')}</div><p class="metric-note">Synthetic seed visits are excluded from recording-time metrics. No field pilot, time-saving estimate, or speech accuracy result is claimed.</p><section class="panel"><div class="panel-header"><h2>Audit trail</h2>${badge(RULE_VERSION)}</div><div class="table-scroll"><table class="wide-table"><thead><tr><th>TIME</th><th>AGENT / ACTOR</th><th>ACTION</th><th>RULE VERSION</th></tr></thead><tbody>${state.audit.map(a=>`<tr><td>${new Date(a.timestamp).toLocaleString('en-IN')}</td><td>${esc(a.agent)}</td><td>${esc(a.action)}</td><td>${esc(a.rule_version)}</td></tr>`).join('')}</tbody></table></div></section>`;}
function settings(){return `${heading('Built on trust','Understand what happens to your records and why a flag appears.')}<section class="content-card"><h2>Storage & offline access</h2><p>Records and audio are stored in IndexedDB on this browser. The app shell is cached after your first online visit. Device data is not encrypted by this demo. Use synthetic data only.</p><div class="detail-grid"><div><small>CONNECTION</small><strong>${navigator.onLine?'Online':'Offline'}</strong></div><div><small>LOCAL CHANGES AWAITING BACKUP</small><strong>${state.outbox.length} records</strong></div><div><small>LAST SERVER BACKUP</small><strong>${state.lastSynced?new Date(state.lastSynced).toLocaleString('en-IN'):'Not backed up'}</strong></div><div><small>BACKEND</small><strong>Optional local Python server</strong></div></div><div class="actions"><button class="primary" data-action="sync-now">${icon('refresh')}Try server backup</button><button class="secondary" data-action="export">${icon('download')}Export JSON</button></div><p style="font-size:11px;margin-top:13px">Hosted static demo: export a backup. Local Python server: changes sync to SQLite on reconnect. This is a single-device demo, not shared production storage.</p></section><section class="content-card"><h2>Rules you can trace</h2><div class="notice">Version ${RULE_VERSION}. Reference-backed screening examples, pending clinician review. These rules are not comprehensive and cannot rule out an emergency. No diagnosis, prescription, or drug-dose advice is generated.</div><div class="rule-list">${RULES.map(r=>`<div class="rule-item"><h3>${r.title}</h3><p>${r.detail}</p><small>${r.id} · <a href="${r.source}" target="_blank" rel="noopener noreferrer">Official reference ↗</a></small></div>`).join('')}</div></section><section class="content-card"><h2>Integration status</h2><p>Speech: browser recognition (English / Hindi; browser support varies). Extraction: deterministic demo parser with worker confirmation. AgentFoundry and xSpan CareHub: not connected. No external clinical or messaging service is called.</p></section>`;}
function render(){const views={overview,beneficiaries:beneficiaryPage,visits:visitsPage,followups,referrals:referralsPage,supervisor,insights,settings,record:recordPage};app.innerHTML=shell((views[page]||overview)());document.documentElement.lang=state.settings.language==='hi-IN'?'hi':'en';}
function openModal(name,body){modal.innerHTML=`<div class="modal-head"><h2>${esc(name)}</h2><button class="icon-btn" aria-label="Close dialog" data-action="close">${icon('close')}</button></div>${body}`;if(!modal.open)modal.showModal();}
function showPerson(id){const b=beneficiary(id),vs=state.visits.filter(v=>v.beneficiary_id===id);openModal(b.name,`<div class="detail-grid"><div><small>BENEFICIARY ID</small><strong>${esc(b.code)}</strong></div><div><small>CARE GROUP</small><strong>${categoryLabels[b.category]}</strong></div><div><small>AGE</small><strong>${b.age_months!=null?`${b.age_months} months`:`${b.age} years`}</strong></div><div><small>HOUSEHOLD</small><strong>${esc(b.village)} · Ward ${esc(b.ward)}</strong></div></div><h3>Recent visits (${vs.length})</h3>${vs.map(v=>`<div class="quote" style="margin-top:12px">${esc(v.transcript)}</div>`).join('')||'<p class="empty">No recorded visits yet.</p>'}<div class="actions"><button class="primary" data-action="new-visit" data-id="${b.id}">${icon('mic')}Record a visit</button></div>`);}
function showTask(id){const t=state.tasks.find(t=>t.id===id),b=beneficiary(t.beneficiary_id);openModal(t.type,`<p>${esc(b.name)} · ${esc(b.code)}</p><div class="detail-grid"><div><small>DUE DATE</small><strong>${esc(t.due_date)} · ${dueLabel(t.due_date)}</strong></div><div><small>CREATED BY</small><strong>${esc(t.source)}</strong></div></div><div class="actions"><button class="primary" data-action="complete-task" data-id="${id}">${icon('check')}Mark completed</button><button class="secondary" data-action="new-visit" data-id="${b.id}">Record visit</button></div>`);}
function showFlag(id){const f=state.flags.find(f=>f.id===id);openModal(`${beneficiary(f.beneficiary_id).name} · Priority case`,`${badge(f.severity.toUpperCase(),'red')}<div class="quote" style="margin:16px 0">${esc(f.reason)}\n\n${esc(f.action)}</div><p style="font-size:11px;color:var(--muted)">Rule: ${esc(f.rule_id)} · Version: ${esc(f.rule_version)}</p><div class="notice">Decision support only. Contact the ANM / PHC and follow official protocols. A flag is not a diagnosis.</div><div class="actions"><button class="primary" data-action="draft-referral" data-id="${id}">${icon('file')}Draft referral</button><button class="secondary" data-action="resolve-form" data-id="${id}">Resolve / dismiss flag</button></div>`);}
function showVisit(id){const v=state.visits.find(v=>v.id===id);openModal(`${beneficiary(v.beneficiary_id).name} · Visit`,`${badge('Confirmed by health worker','green')}<div class="quote" style="margin:16px 0">${esc(v.transcript)}</div><div class="detail-grid">${Object.entries(v.structured).filter(([k,val])=>['bp_systolic','bp_diastolic','muac_cm','gestation_months','cough_days','advice'].includes(k)&&val!=null&&val!=='').map(([k,val])=>`<div><small>${k.replaceAll('_',' ').toUpperCase()}</small><strong>${esc(val)}</strong></div>`).join('')}</div>${state.flags.filter(f=>f.visit_id===id).map(alertCard).join('')}${v.audio?'<button class="secondary" data-action="play-audio" data-id="'+id+'">'+icon('volume')+'Play saved audio</button><div id="saved-audio"></div>':''}`);}
function showReferral(id){const r=state.referrals.find(r=>r.id===id);openModal('Referral draft',`<div class="form-field"><label for="referral-text">Review and edit before sharing</label><textarea id="referral-text" rows="12">${esc(r.drafted_text)}</textarea></div><div class="actions"><button class="primary" data-action="copy-referral" data-id="${id}">Copy draft</button><button class="secondary" data-action="save-referral" data-id="${id}">Save edits</button></div><p style="font-size:11px;color:var(--muted);margin-top:15px">Share through your approved channel. Copying does not send this referral.</p>`);}
function personForm(){openModal('Add a beneficiary',`<form id="person-form"><div class="form-grid"><div class="form-field full"><label for="person-name">Demo name / pseudonym</label><input id="person-name" name="name" required maxlength="80"></div><div class="form-field"><label for="person-category">Care group</label><select id="person-category" name="category">${Object.entries(categoryLabels).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></div><div class="form-field"><label for="person-age">Age in months (children) or years (adults)</label><input id="person-age" name="age" type="number" min="0" max="120" required></div><div class="form-field"><label for="person-village">Village</label><input id="person-village" name="village" value="Rampur" required maxlength="80"></div><div class="form-field"><label for="person-ward">Ward</label><input id="person-ward" name="ward" required maxlength="10"></div></div><label class="check"><input name="consent" type="checkbox" required>Consent to maintain this demo record is captured.</label><button class="primary" type="submit">Add beneficiary</button></form>`);}
function taskForm(){openModal('Plan a follow-up',`<form id="task-form"><div class="form-field"><label for="task-person">Beneficiary</label><select id="task-person" name="beneficiary_id">${state.beneficiaries.map(b=>`<option value="${b.id}">${esc(b.name)}</option>`).join('')}</select></div><div class="form-field"><label for="task-type">Follow-up action</label><input id="task-type" name="type" required maxlength="150" placeholder="e.g. Antenatal home visit"></div><div class="form-field"><label for="task-date">Due date</label><input id="task-date" name="due_date" type="date" required value="${dateKey()}"></div><button class="primary" type="submit">Save follow-up</button></form>`);}
async function startRecording(){if(!document.querySelector('#consent').checked){toast('Please capture consent before recording.');return;}if(!navigator.mediaDevices?.getUserMedia){toast('Audio recording is unavailable. Type the visit note below.');return;}
 try{const stream=await navigator.mediaDevices.getUserMedia({audio:true});if(page!=='record'||draft?.stage==='review'){stream.getTracks().forEach(t=>t.stop());return;}audioChunks=[];recordingAudio=new MediaRecorder(stream);const recorder=recordingAudio;const recordingDraft=draft;recorder.ondataavailable=e=>{if(e.data.size)audioChunks.push(e.data);};pendingAudio=new Promise(resolve=>{recorder.onstop=()=>{const blob=new Blob(audioChunks,{type:recorder.mimeType||'audio/webm'});if(recordingDraft)recordingDraft.audio=blob;stream.getTracks().forEach(t=>t.stop());if(audioURL)URL.revokeObjectURL(audioURL);audioURL=URL.createObjectURL(blob);const el=document.querySelector('#audio-preview');if(el){el.innerHTML='<audio controls style="width:100%;margin-bottom:15px"></audio>';el.firstChild.src=audioURL;}resolve(blob);};});recorder.start();recordingActive=true;recordStart=Date.now();const btn=document.querySelector('#record-toggle');btn.classList.add('recording');btn.setAttribute('aria-label','Stop recording');document.querySelector('#record-label').textContent='Listening… tap to finish';const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(SR){recording=new SR();recording.lang=state.settings.language;recording.continuous=true;recording.interimResults=false;recording.onresult=e=>{const el=document.querySelector('#transcript');if(el){for(let i=e.resultIndex;i<e.results.length;i++)if(e.results[i].isFinal)el.value+=(el.value?' ':'')+e.results[i][0].transcript;}};recording.onerror=e=>{if(e.error!=='aborted')toast('Speech recognition unavailable. Audio is retained; type the visit note.');};recording.start();}else toast('Audio recording started. Live transcription is unsupported in this browser.');recorderTimer=setTimeout(()=>{stopRecording();toast('Recording stopped at the 3-minute limit.');},180000);
 }catch(e){stopRecording();toast('Microphone unavailable or permission denied. You can type the visit instead.');}}
function stopRecording(){clearTimeout(recorderTimer);if(recording){try{recording.stop();}catch{}recording=null;}if(recordingAudio&&recordingAudio.state!=='inactive'){recordingAudio.stop();}recordingAudio=null;recordingActive=false;document.querySelector('#record-toggle')?.classList.remove('recording');const label=document.querySelector('#record-label');if(label)label.textContent='Recording finished · review your note';}
async function sync(quiet=false){if(!navigator.onLine){if(!quiet)toast('Offline. Your changes are saved on this device.');return;}try{const response=await fetch('/api/health',{signal:AbortSignal.timeout(4000)});if(!response.ok)throw Error();const health=await response.json();if(health.service!=='asha-sahayak-demo')throw Error();const snapshot=JSON.parse(JSON.stringify(state,(k,v)=>k==='audio'?undefined:v));const ids=state.outbox.map(o=>o.id);const response2=await fetch('/api/sync',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({state:snapshot}),signal:AbortSignal.timeout(10000)});if(!response2.ok)throw Error();const result=await response2.json();if(result.ok!==true)throw Error();state.outbox=state.outbox.filter(o=>!ids.includes(o.id));state.lastSynced=new Date().toISOString();await persist();if(page!=='record')render();if(!quiet)toast('Records backed up to the local SQLite server. Audio remains on this device.');}catch{if(!quiet)toast('Backup server unavailable. Records remain saved locally; use Export JSON.');}}
function enqueue(type,id){state.outbox.push({id:uid(),type,record_id:id,timestamp:new Date().toISOString()});}
async function saveVisit(form){if(saveBusy)return;const data=new FormData(form),r={...draft.record};for(const key of ['bp_systolic','bp_diastolic','muac_cm','gestation_months','cough_days']){const val=data.get(key);if(val!==null)r[key]=val===''?null:Number(val);}r.symptoms=String(data.get('symptoms')).split(',').map(s=>s.trim().toLowerCase().replaceAll(' ','_')).filter(Boolean);r.advice=String(data.get('advice')||'').trim();const errors=validate(r);if(errors.length){toast(errors[0]);return;}saveBusy=true;form.querySelector('[type=submit]').disabled=true;const before=structuredClone(state);try{const flags=guardian(triage(r)),visit={id:uid(),beneficiary_id:r.beneficiary_id,asha_id:'demo-lakshmi',timestamp:new Date().toISOString(),transcript:draft.transcript,structured:r,confirmed_by_asha:true,consent:true,duration_seconds:Math.max(1,Math.round((Date.now()-draft.started)/1000)),audio:draft.audio||null,synthetic:false};state.visits.push(visit);state.flags.push(...flags.map(f=>({...f,visit_id:visit.id,beneficiary_id:r.beneficiary_id})));state.tasks.push(...plan(r,flags));if(flags.some(f=>f.severity==='urgent'))state.referrals.push({id:uid(),visit_id:visit.id,beneficiary_id:r.beneficiary_id,timestamp:visit.timestamp,drafted_text:draftReferral(beneficiary(r.beneficiary_id),r,flags),status:'draft',sent_at:null});for(const [agent,action] of [['Scribe','Visit reviewed and confirmed'],['Triage',`${flags.length} screening flag(s) raised`],['Guardian','Flag reasons and source rules checked'],['Care Planner',`${flags.length?'Clinical follow-up planned':'No automatic follow-up indicated'}`],...(flags.some(f=>f.severity==='urgent')?[['Escalation','Referral drafted for worker review']]:[])])audit(agent,`${beneficiary(r.beneficiary_id).name}: ${action}`,{visit_id:visit.id});enqueue('visit',visit.id);await persist();draft=null;navigate('visits');toast(flags.length?'Visit saved. Review the flags and planned follow-ups.':'Visit saved on this device.');showVisit(visit.id);sync(true);}catch(e){state=before;toast('Could not save this visit. Your draft is still available; try again.');form.querySelector('[type=submit]').disabled=false;}finally{saveBusy=false;}}
async function handleAction(action,id,el){switch(action){case'menu':document.querySelector('.sidebar').classList.toggle('open');break;case'close':modal.close();break;case'new-visit':modal.close();stopRecording();pendingAudio=null;draft={beneficiary_id:id||state.beneficiaries[0]?.id,stage:'capture',transcript:'',started:Date.now()};navigate('record');break;case'sample':document.querySelector('#visit-person').value='b1';document.querySelector('#transcript').value=state.settings.language==='hi-IN'?'सावित्री 7 महीने की गर्भवती। बीपी 150 बाय 100। सिर दर्द और सूजन।':'Visited Savitri, 7 months pregnant. BP 150 by 100. She reports a headache and swelling in her feet.';break;case'record-toggle':recordingActive?stopRecording():await startRecording();break;case'extract':{const transcript=document.querySelector('#transcript').value.trim(),consent=document.querySelector('#consent').checked,b=beneficiary(document.querySelector('#visit-person').value);if(!consent){toast('Capture consent before reviewing the visit.');return;}if(transcript.length<5){toast('Record or type a short visit note first.');return;}stopRecording();if(pendingAudio)await pendingAudio;const result=extract(transcript,b);draft={...draft,...result,transcript,consent,beneficiary_id:b.id,stage:'review'};render();break;}case'edit-draft':draft.stage='capture';render();break;case'readback':{if(!window.speechSynthesis){toast('Read-back is unavailable in this browser. Review the text.');return;}const data=new FormData(document.querySelector('#confirm-form'));const b=beneficiary(draft.beneficiary_id);const text=state.settings.language==='hi-IN'?`${b.name}। रक्तचाप ${data.get('bp_systolic')||'दर्ज नहीं'} और ${data.get('bp_diastolic')||'दर्ज नहीं'}। लक्षण ${data.get('symptoms')||'दर्ज नहीं'}। कृपया जाँच करें।`:`${b.name}. Blood pressure ${data.get('bp_systolic')||'not recorded'} over ${data.get('bp_diastolic')||'not recorded'}. Reported symptoms: ${data.get('symptoms')||'none recorded'}. Please confirm the details.`;speechSynthesis.cancel();const speech=new SpeechSynthesisUtterance(text);speech.lang=state.settings.language;speechSynthesis.speak(speech);break;}case'person':showPerson(id);break;case'visit':showVisit(id);break;case'task':showTask(id);break;case'flag':showFlag(id);break;case'referral':showReferral(id);break;case'add-person':personForm();break;case'add-task':taskForm();break;case'complete-task':{const t=state.tasks.find(t=>t.id===id);t.status='completed';t.completed_at=new Date().toISOString();audit('Health worker',`${beneficiary(t.beneficiary_id).name}: ${t.type} completed`);enqueue('task',id);await persist();modal.close();render();toast('Follow-up marked completed.');break;}case'resolve-form':openModal('Resolve or dismiss flag',`<form id="resolve-form" data-id="${id}"><div class="form-field"><label for="resolution">Action</label><select id="resolution" name="status"><option value="resolved">Resolved — clinical follow-up completed</option><option value="dismissed">Dismissed — worker override</option></select></div><div class="form-field"><label for="reason">Reason / outcome (required)</label><textarea id="reason" name="reason" required minlength="5" maxlength="1000"></textarea></div><button class="primary" type="submit">Save to audit trail</button></form>`);break;case'draft-referral':{const f=state.flags.find(f=>f.id===id),v=state.visits.find(v=>v.id===f.visit_id);let referral=state.referrals.find(r=>r.visit_id===v.id);if(!referral){referral={id:uid(),visit_id:v.id,beneficiary_id:f.beneficiary_id,timestamp:new Date().toISOString(),drafted_text:draftReferral(beneficiary(f.beneficiary_id),v.structured,state.flags.filter(x=>x.visit_id===v.id)),status:'draft',sent_at:null};state.referrals.push(referral);audit('Escalation',`${beneficiary(f.beneficiary_id).name}: referral drafted`);enqueue('referral',referral.id);await persist();}showReferral(referral.id);break;}case'save-referral':case'copy-referral':{const text=document.querySelector('#referral-text').value;state.referrals.find(r=>r.id===id).drafted_text=text;enqueue('referral',id);await persist();if(action==='copy-referral'){try{await navigator.clipboard.writeText(text);toast('Draft copied. Share through your approved channel.');}catch{document.querySelector('#referral-text').select();toast('Select and copy the draft manually.');}}else toast('Draft edits saved.');break;}case'play-audio':{const v=state.visits.find(v=>v.id===id);if(audioURL)URL.revokeObjectURL(audioURL);audioURL=URL.createObjectURL(v.audio);const audio=document.createElement('audio');audio.controls=true;audio.src=audioURL;audio.style.width='100%';document.querySelector('#saved-audio').replaceChildren(audio);audio.play().catch(()=>{});break;}case'sync':navigate('settings');break;case'sync-now':await sync();break;case'export':{const blob=new Blob([JSON.stringify(state,(k,v)=>k==='audio'?undefined:v,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`asha-sahayak-${dateKey()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Export downloaded. Audio is stored separately on this device.');break;}}}
document.addEventListener('click',async e=>{const nav=e.target.closest('[data-nav]'),f=e.target.closest('[data-filter]'),action=e.target.closest('[data-action]');try{if(nav){modal.close();navigate(nav.dataset.nav);}else if(f){filter=f.dataset.filter;render();}else if(action){const previousState=structuredClone(state);action.disabled=true;try{await handleAction(action.dataset.action,action.dataset.id,action);}catch(err){state=previousState;throw err;}finally{action.disabled=false;}}}catch(err){console.error(err);toast('That action could not be saved. Please try again.');}});
document.addEventListener('change',async e=>{if(e.target.id==='language'){if(page==='record'&&draft?.stage!=='review'){draft.transcript=document.querySelector('#transcript').value;draft.consent=document.querySelector('#consent').checked;draft.beneficiary_id=document.querySelector('#visit-person').value;}stopRecording();state.settings.language=e.target.value;await persist();render();}if(e.target.id==='category-filter'){filter=e.target.value;render();}});
document.addEventListener('input',e=>{if(e.target.id==='search'){const position=e.target.selectionStart;search=e.target.value;render();const input=document.querySelector('#search');input.focus();input.setSelectionRange(position,position);}});
document.addEventListener('submit',async e=>{e.preventDefault();const form=e.target;if(form.id==='confirm-form'){await saveVisit(form);return;}const data=new FormData(form);const before=structuredClone(state);try{if(form.id==='person-form'){const category=data.get('category'),child=['child','infant'].includes(category);const b={id:uid(),name:String(data.get('name')).trim(),code:`AS-${String(state.beneficiaries.length+1).padStart(3,'0')}`,category,age:child?Math.floor(Number(data.get('age'))/12):Number(data.get('age')),age_months:child?Number(data.get('age')):null,household_id:uid(),village:String(data.get('village')).trim(),ward:String(data.get('ward')).trim(),consent:true,color:'green'};if(!b.name||!b.village||!b.ward)throw Error('Fill all required fields.');state.beneficiaries.push(b);state.households.push({id:b.household_id,village:b.village,ward:b.ward,consent_status:'captured'});audit('Health worker',`${b.name}: beneficiary added with consent`);enqueue('beneficiary',b.id);}else if(form.id==='task-form'){const t={id:uid(),beneficiary_id:data.get('beneficiary_id'),type:String(data.get('type')).trim(),due_date:data.get('due_date'),status:'pending',source:'Health worker'};if(!t.type)throw Error('Enter a follow-up action.');state.tasks.push(t);audit('Health worker',`${beneficiary(t.beneficiary_id).name}: follow-up added`);enqueue('task',t.id);}else if(form.id==='resolve-form'){const f=state.flags.find(f=>f.id===form.dataset.id);f.status=data.get('status');f.resolution=String(data.get('reason')).trim();if(f.resolution.length<5)throw Error('Please enter a meaningful reason.');audit('Health worker',`${f.rule_id} ${f.status}: ${f.resolution}`,{flag_id:f.id});enqueue('flag',f.id);}else return;await persist();modal.close();render();toast('Saved on this device.');}catch(err){state=before;toast(err.message||'Unable to save. Please try again.');}});
window.addEventListener('online',()=>{if(page!=='record')render();sync(true);});window.addEventListener('offline',()=>{if(page!=='record')render();toast('Offline. You can continue recording and saving visits.');});
modal.addEventListener('close',()=>{if(audioURL){URL.revokeObjectURL(audioURL);audioURL=null;}});
try{await openStore();state=await readState();if(!state){state=seed();await persist();}render();if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>toast('Offline app caching is unavailable in this browser.'));}catch(err){app.innerHTML='<main><h1>Local storage is unavailable</h1><p>Enable browser storage and reload to use ASHA Sahayak. Records cannot be safely saved in this browser session.</p></main>';console.error(err);}
